#include<bits/stdc++.h>
#include<atcoder/segtree>

using namespace std;
using namespace atcoder;

typedef struct{
  char lefc;
  int lefn;
  char rigc;
  int rign;
  bool con;
  int ans;
}S;

S e(){
  return {'*',0,'*',0,true,0};
}

S op(S l,S r){
  if(l.lefc=='*'){return r;}
  if(r.lefc=='*'){return l;}

  S res;
  res.ans=max(l.ans,r.ans);

  if(l.con && r.con){
    if(l.lefc==r.lefc){
      res.lefc=l.lefc;
      res.lefn=(l.lefn+r.lefn);
      res.con=true;
    }
    else{
      res.lefc=l.lefc;
      res.lefn=l.lefn;
      res.rigc=r.lefc;
      res.rign=r.lefn;
      res.con=false;
    }
  }
  else if(l.con){
    res.con=false;
    if(l.lefc==r.lefc){
      res.lefc=l.lefc;
      res.lefn=l.lefn+r.lefn;
    }
    else{
      res.lefc=l.lefc;
      res.lefn=l.lefn;
    }
    res.rigc=r.rigc;
    res.rign=r.rign;
  }
  else if(r.con){
    res.con=false;
    res.lefc=l.lefc;
    res.lefn=l.lefn;
    if(l.rigc==r.lefc){
      res.rigc=r.lefc;
      res.rign=l.rign+r.lefn;
    }
    else{
      res.rigc=r.lefc;
      res.rign=r.lefn;
    }
  }
  else{
    res.con=false;
    res.lefc=l.lefc;
    res.lefn=l.lefn;
    res.rigc=r.rigc;
    res.rign=r.rign;
    if(l.rigc==r.lefc){
      res.ans=max(res.ans,l.rign+r.lefn);
    }
  }

  res.ans=max(res.ans,max(res.lefn,res.rign));

  return res;
}

S cvrt(char c){
  return {c,1,'*',0,true,1};
}

int main(){
  int n,q;
  cin >> n >> q;
  string s;
  cin >> s;
  vector<S> ini(n);
  for(int i=0;i<n;i++){
    ini[i]=cvrt(s[i]);
  }
  segtree<S,op,e> seg(ini);
  while(q>0){
    q--;
    int typ;
    cin >> typ;
    if(typ==1){
      int i;
      char x;
      cin >> i >> x;
      seg.set(i-1,cvrt(x));
    }
    else{
      int l,r;
      cin >> l >> r;
      cout << seg.prod(l-1,r).ans << "\n";
    }
  }
  return 0;
}
